// 作者: @新哥AGI研习社
// 代码功能：解析飞书消息事件，提取文本或图片信息（支持 message_type 为 text / image）

// 获取第一个输入项的json.body作为事件数据
const event = $input.first().json.body;

// 检查是否为消息事件（event_type必须是'im.message.receive_v1'）
if (!event.header || event.header.event_type !== 'im.message.receive_v1') {
  // 如果不是消息事件，返回对应的错误码和错误描述
  return [
    {
      json: {
        code: 40001,
        error: '非消息事件',
      },
    },
  ];
}

// 获取消息内容对象
const message = event.event.message;
// 获取发送者信息对象
const sender = event.event.sender;
// 当前消息类型（text 文本 / image 图片等）
const messageType = message.message_type;

// 解析消息中的 content 字段：飞书多为 JSON 字符串，亦可能已是对象；解析失败则返回错误
function parseMessageContent(raw) {
  if (raw == null || raw === '') {
    return null;
  }
  if (typeof raw === 'object') {
    return raw;
  }
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

const content = parseMessageContent(message.content);
if (!content) {
  // 如果 content 无法解析，返回对应的错误码和错误描述
  return [
    {
      json: {
        code: 40003,
        error: '消息 content 无法解析为 JSON',
        message_type: messageType,
        message_id: message.message_id
      },
    },
  ];
}

// 从sender对象中提取用户open_id
const userOpenId = sender.sender_id.open_id;

// 提取消息所属的群组ID
const chatId = event.event.message.chat_id;
// 提取聊天类型（如单聊group或群聊p2p等）
const chatType = event.event.message.chat_type;

// 各类型共用的成功返回骨架
const baseOk = {
  code: 200,
  message_type: messageType,
  user_open_id: userOpenId,
  chat_id: chatId,
  chat_type: chatType,
  message_id: message.message_id,
  create_time: message.create_time,
};

// 文本消息：从 content 中取 text
if (messageType === 'text') {
  const text = typeof content.text === 'string' ? content.text : '';
  if (!text) {
    // 如果文本消息缺少有效 text，返回对应的错误码和错误描述
    return [
      {
        json: {
          code: 40004,
          error: '文本消息缺少 text 字段',
          message_type: messageType,
          message_id: message.message_id
        },
      },
    ];
  }
  // 返回文本记账所需字段；has_image 为 false 表示非图片链路
  return [
    {
      json: {
        ...baseOk,
        text,
        image_key: null,
        has_image: false,
      },
    },
  ];
}

// 图片消息：从 content 中取 image_key
if (messageType === 'image') {
  const imageKey = content.image_key;
  if (!imageKey || typeof imageKey !== 'string') {
    // 如果图片消息缺少 image_key，返回对应的错误码和错误描述
    return [
      {
        json: {
          code: 40005,
          error: '图片消息缺少 image_key',
          message_type: messageType,
          message_id: message.message_id
        },
      },
    ];
  }
  // 返回提取的关键信息，结构化输出，has_image 表明已抓取到图片消息
  return [
    {
      json: {
        ...baseOk,
        text: null,
        image_key: imageKey,
        has_image: true,
      },
    },
  ];
}

// 如果不是支持的 text / image 类型，返回对应的错误码和错误描述，并带上消息类型
return [
  {
    json: {
      code: 40002,
      error: '不支持的消息类型',
      message_type: messageType,
      message_id: message.message_id
    },
  },
];

